    // ---- 4. end-to-end facade ----------------------------------------------------------------

    /// <summary>Resolves a repo-relative path by walking up to the .sbproj directory.</summary>
    private static string RepoFile(params string[] parts)
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            if (File.Exists(Path.Combine(dir.FullName, "humanoid-retargeter.sbproj")))
                return Path.Combine(new[] { dir.FullName }.Concat(parts).ToArray());
            dir = dir.Parent!;
        }
        throw new InvalidOperationException("Repo root (humanoid-retargeter.sbproj) not found.");
    }

    [Fact]
    public void Facade_ConvertGlbToSboxTarget_SucceedsWithDetectedProfile()
    {
        var target = RetargetTargetSpec.SboxDefault(
            File.ReadAllText(RepoFile("Assets", "data", "humanoid_retargeter", "target_rig_sbox.json")));

        var result = Retargeter.Convert(new RetargetRequest
        {
            SourceData = Fixture("freebvh.glb"),
            SourceFileName = "freebvh.glb",
        }, target);

        Assert.True(result.Success, string.Join("; ", result.Errors));
        var clip = Assert.Single(result.Clips);
        Assert.True(clip.Success, clip.Error);
        Assert.False(string.IsNullOrEmpty(clip.DmxContent));
        Assert.Contains("pelvis_p", clip.DmxContent);

        // The rig keeps its mixamorig names through Blender's glTF export → the shipped
        // mixamo preset must detect at preset-grade confidence.
        Assert.NotNull(clip.Mapping);
        Assert.Equal("mixamo", clip.Mapping!.ProfileName);
        Assert.False(clip.Mapping.NeedsUserDecision);
        Assert.True(clip.Mapping.Confidence >= 0.8f, $"confidence {clip.Mapping.Confidence}");

        // Inspect (UI listing path) sees the same profile and the single take.
        var inspected = Retargeter.Inspect(Fixture("freebvh.glb"), "freebvh.glb");
        Assert.Equal("mixamo", inspected.Mapping.ProfileName);
        Assert.Equal(1, inspected.TakeCount);
    }

    // ---- 5. robustness: hostile / malformed files --------------------------------------------
    // Contract: anything malformed throws FormatException — never StackOverflow (uncatchable,
    // kills the host editor), never OverflowException, never an OOM allocation bomb.

    [Fact]
    public void GltfJson_CyclicChildrenGraph_ThrowsFormatException()
    {
        // B and C list each other as children (a cycle reachable from "root"): the node DFS
        // must detect the revisit instead of recursing unboundedly (StackOverflow).
        var json = """
            {
                "asset": { "version": "2.0" },
                "nodes": [
                    { "name": "B", "children": [1] },
                    { "name": "C", "children": [0] },
                    { "name": "root", "children": [0] }
                ],
                "skins": [ { "joints": [0, 1] } ]
            }
            """;
        var e = Assert.Throws<FormatException>(
            () => GltfImporter.Import(Encoding.UTF8.GetBytes(json)));
        Assert.Contains("cycle", e.Message, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public void GltfJson_SelfParentedAncestorChain_ThrowsFormatException()
    {
        // Z lists ITSELF as a child (self-parent) and also parents the skinned joint B; Z is
        // unreachable from the root, so the nearest-kept-ancestor walk from B (B.Parent = Z,
        // Z.Parent = Z) would loop forever without a visited guard.
        var json = """
            {
                "asset": { "version": "2.0" },
                "nodes": [
                    { "name": "Z", "children": [0, 2] },
                    { "name": "root", "children": [2] },
                    { "name": "B" }
                ],
                "skins": [ { "joints": [2] } ]
            }
            """;
        var e = Assert.Throws<FormatException>(
            () => GltfImporter.Import(Encoding.UTF8.GetBytes(json)));
        Assert.Contains("cycle", e.Message, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>Synthetic one-node scene whose sampler accessors carry an arbitrary count
    /// (the times buffer really holds 2 keys = 8 bytes).</summary>
    private static string GltfWithAccessorCount(string count, bool withBufferView = true)
    {
        var times = Base64Floats(0f, 1f);
        var rotations = Base64Floats(0f, 0f, 0f, 1f, 0f, 0f, 0f, 1f);
        var timesView = withBufferView ? "\"bufferView\": 0, " : "";
        return $$"""
            {
                "asset": { "version": "2.0" },
                "nodes": [ { "name": "solo" } ],
                "animations": [ {
                    "channels": [ { "sampler": 0, "target": { "node": 0, "path": "rotation" } } ],
                    "samplers": [ { "input": 0, "output": 1, "interpolation": "LINEAR" } ]
                } ],
                "buffers": [
                    { "byteLength": 8, "uri": "data:application/octet-stream;base64,{{times}}" },
                    { "byteLength": 32, "uri": "data:application/octet-stream;base64,{{rotations}}" }
                ],
                "bufferViews": [
                    { "buffer": 0, "byteOffset": 0, "byteLength": 8 },
                    { "buffer": 1, "byteOffset": 0, "byteLength": 32 }
                ],
                "accessors": [
                    { {{timesView}}"componentType": 5126, "count": {{count}}, "type": "SCALAR" },
                    { "bufferView": 1, "componentType": 5126, "count": 2, "type": "VEC4" }
                ]
            }
            """;
    }

    [Fact]
    public void GltfJson_NegativeAccessorCount_ThrowsFormatException()
    {
        // count = -1 would throw OverflowException from the array allocation (breaking the
        // FormatException malformed-file contract) without up-front validation.
        var e = Assert.Throws<FormatException>(() => GltfImporter.Import(
            Encoding.UTF8.GetBytes(GltfWithAccessorCount("-1"))));
        Assert.Contains("count", e.Message, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public void GltfJson_HugeAccessorCount_ThrowsFormatException_BeforeAllocating()
    {
        // count = 4e8 on an 8-byte buffer: the bounds check must run BEFORE the allocation
        // (1.6 GB) — a fast FormatException here is itself the no-OOM proof.
        Assert.Throws<FormatException>(() => GltfImporter.Import(
            Encoding.UTF8.GetBytes(GltfWithAccessorCount("400000000"))));

        // bufferView-less accessors are zero-filled per spec, but the count is then backed
        // by nothing: it must be capped by the file's total buffer payload.
        Assert.Throws<FormatException>(() => GltfImporter.Import(
            Encoding.UTF8.GetBytes(GltfWithAccessorCount("400000000", withBufferView: false))));
    }

    [Fact]
    public void GltfJson_HugeKeyTimeSpan_ThrowsFormatException()
    {
        // Two keys spanning 1e7 s would resample to 3e8 frames at 30 fps (OOM), and the
        // unchecked double→int conversion could wrap and get masked to a 1-frame clip.
        var times = Base64Floats(0f, 1e7f);
        var rotations = Base64Floats(0f, 0f, 0f, 1f, 0f, 0f, 0f, 1f);
        var json = $$"""
            {
                "asset": { "version": "2.0" },
                "nodes": [ { "name": "solo" } ],
                "animations": [ {
                    "channels": [ { "sampler": 0, "target": { "node": 0, "path": "rotation" } } ],
                    "samplers": [ { "input": 0, "output": 1, "interpolation": "LINEAR" } ]
                } ],
                "buffers": [
                    { "byteLength": 8, "uri": "data:application/octet-stream;base64,{{times}}" },
                    { "byteLength": 32, "uri": "data:application/octet-stream;base64,{{rotations}}" }
                ],
                "bufferViews": [
                    { "buffer": 0, "byteOffset": 0, "byteLength": 8 },
                    { "buffer": 1, "byteOffset": 0, "byteLength": 32 }
                ],
                "accessors": [
                    { "bufferView": 0, "componentType": 5126, "count": 2, "type": "SCALAR" },
                    { "bufferView": 1, "componentType": 5126, "count": 2, "type": "VEC4" }
                ]
            }
            """;
        var e = Assert.Throws<FormatException>(
            () => GltfImporter.Import(Encoding.UTF8.GetBytes(json)));
        // The offending span must be named in the message.
        Assert.Contains("span", e.Message, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("10000000", e.Message);
    }

    // ---- 6. resampling ----------------------------------------------------------------------

    [Theory]
    [InlineData(30f)]
    [InlineData(60f)]
    [InlineData(15f)]
    public void Glb_Resampling_FrameCountMatchesGrid(float fps)
    {
        var scene = ImportGlb(fps);
        var clip = Assert.Single(scene.Clips);
        Assert.Equal(fps, clip.Fps);

        // freebvh: 69 baked keys at ~30 fps → duration ≈ 68/30.00003 s.
        double duration = 68.0 / 30.000030;
        Assert.Equal((int)Math.Round(duration * fps) + 1, clip.FrameCount);
    }
}
